<script setup lang="ts">
import {computed,ref} from 'vue'
import {Search,Check} from '@lucide/vue'
import CategoryIcon from './CategoryIcon.vue'
import {categoryIconOptions,categoryIconGroups,resolveCategoryIcon} from './categoryIcons'
const props=withDefaults(defineProps<{modelValue:string;color?:string;categoryName?:string;flowType?:'expense'|'income'}>(),{color:'currentColor',categoryName:''})
const emit=defineEmits<{'update:modelValue':[value:string]}>()
const query=ref(''),group=ref('all')
const selected=computed(()=>resolveCategoryIcon(props.modelValue,{name:props.categoryName,flowType:props.flowType}))
const visible=computed(()=>categoryIconOptions.filter(option=>(group.value==='all'||option.group===group.value)&&`${option.label} ${option.id} ${option.group}`.toLowerCase().includes(query.value.trim().toLowerCase())))
</script>
<template><section class="category-symbol-picker" aria-label="分类图标"><header><span class="csp-preview" :style="{color}"><CategoryIcon :name="modelValue" :category-name="categoryName" :flow-type="flowType" :size="26"/></span><div><b>选一个容易认出的图标</b><small>当前：{{ selected.label }} · {{ categoryIconOptions.length }} 款可选</small></div></header><label class="csp-search"><Search :size="16"/><input v-model="query" type="search" aria-label="搜索分类图标" placeholder="搜索咖啡、停车、工资…"/></label><nav class="csp-groups" aria-label="图标分组"><button type="button" :class="{active:group==='all'}" :aria-pressed="group==='all'" @click="group='all'">全部</button><button v-for="label in categoryIconGroups" :key="label" type="button" :class="{active:group===label}" :aria-pressed="group===label" @click="group=label">{{ label }}</button></nav><div class="csp-grid"><button v-for="option in visible" :key="option.id" type="button" :class="{selected:selected.kind==='svg'&&selected.key===option.id}" :aria-pressed="selected.kind==='svg'&&selected.key===option.id" :aria-label="`${option.label}图标`" :style="{'--chosen-color':color}" @click="emit('update:modelValue',option.id)"><CategoryIcon :name="option.id" :size="24"/><span>{{ option.label }}</span><Check v-if="selected.kind==='svg'&&selected.key===option.id" :size="11" class="csp-check"/></button><p v-if="!visible.length" class="csp-empty">没有匹配的图标，试试其他名称或分组。</p></div></section></template>
<style scoped>
