var(--chosen-color,#5891c8);background:var(--ledger-canvas,#f2f5f8);box-shadow:inset 0 0 0 1px var(--chosen-color,#5891c8)}.csp-check{position:absolute;top:5px;right:5px}.csp-empty{grid-column:1/-1;margin:12px 0;padding:20px;text-align:center;font-size:12px;color:var(--ledger-muted,#82919f)}@media(max-width:580px){.csp-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;max-height:268px}.csp-grid>button{min-height:75px}.csp-groups>button{min-height:38px}.csp-search input{font-size:16px}.csp-grid>button>span{font-size:11px}}
